do $$ declare def text; begin select pg_get_functiondef('app.phase2_guard()'::regprocedure) into def; def:=replace(def,'j jsonb:=to_jsonb(new); k text','j jsonb:=to_jsonb(new); hash_field text'); def:=replace(def,'foreach k in array','foreach hash_field in array'); def:=replace(def,'j ? k and j->>k is not null and j->>k','j ? hash_field and j->>hash_field is not null and j->>hash_field'); def:=replace(def,$s$j->>'source_ref'<>'referral:'||j->>'referral_id'$s$,$s$j->>'source_ref'<>('referral:'||(j->>'referral_id'))$s$); execute def; end $$;